full_path = os.path.join(wt, "book/The-Incompleteness-of-Observation-FULL.md")
full = open(full_path, encoding="utf-8").read()
cache = {}
ok = True
news = []
for eid, f, old, new, disp in E:
    if f not in cache: cache[f] = open(os.path.join(wt, f), encoding="utf-8").read()
    c1 = cache[f].count(old); c2 = full.count(old)
    status = "OK" if (c1 == 1 and c2 == 1) else f"COUNT chapter={c1} FULL={c2}"
    if status != "OK": ok = False
    line = cache[f][:cache[f].find(old)].count("\n") + 1 if c1 else None
    fline = full[:full.find(old)].count("\n") + 1 if c2 else None
    print(f"{eid:4s} {os.path.basename(f)}:{line} FULL:{fline} {status}  [{disp}]")
    news.append(new)
open(os.path.join(outdir, "new_texts.txt"), "w", encoding="utf-8").write("\n@@\n".join(n for n in news if n))
print("all old strings unique in chapter and FULL:", ok, "| edits:", len(E))
